public sealed class FulfilmentCoordinator
{
    private readonly Dictionary<string, int> _reservations = new(StringComparer.Ordinal);
    private readonly Dictionary<string, string> _pickNotes = new(StringComparer.Ordinal);
    private readonly Dictionary<string, string> _routes = new(StringComparer.Ordinal);
    private readonly Dictionary<string, string> _exceptions = new(StringComparer.Ordinal);

    public string Reserve(OrderRequest order, IReadOnlyDictionary<string, StockPosition> stock)
    {
        if (string.IsNullOrWhiteSpace(order.Reference)) return "invalid-reference";
        if (order.Lines.Count == 0) return "empty-order";
        if (order.Lines.Any(line => line.Quantity <= 0)) return "invalid-quantity";
        if (order.Lines.Any(line => string.IsNullOrWhiteSpace(line.Sku))) return "invalid-sku";
        if (order.Lines.Any(line => !stock.ContainsKey(line.Sku))) return "unknown-sku";
        if (order.Lines.Any(line => stock[line.Sku].Quarantined)) return "quarantined";
        if (order.Lines.Any(line => stock[line.Sku].OnHand - stock[line.Sku].Reserved < line.Quantity)) return "insufficient-stock";
        _reservations[order.Reference] = order.Lines.Sum(line => line.Quantity);
        return order.Priority ? "reserved-priority" : "reserved";
    }

    public string Release(OrderRequest order, string reason)
    {
        if (string.IsNullOrWhiteSpace(order.Reference)) return "invalid-reference";
        if (!_reservations.ContainsKey(order.Reference)) return "not-reserved";
        if (string.IsNullOrWhiteSpace(reason)) return "reason-required";
        if (reason == "dispatched") return "already-progressed";
        if (order.Lines.Count == 0) return "invalid-order";
        if (order.Lines.Any(line => line.Quantity <= 0)) return "invalid-quantity";
        if (order.Priority && reason == "timeout") return "manual-release-required";
        _reservations.Remove(order.Reference);
        return reason == "cancelled" ? "released-cancelled" : "released";
    }

    public string CreatePickNote(OrderRequest order, IReadOnlyDictionary<string, StockPosition> stock)
    {
        if (string.IsNullOrWhiteSpace(order.Reference)) return "invalid-reference";
        if (order.Lines.Count == 0) return "empty-order";
        if (order.Lines.Any(line => !stock.ContainsKey(line.Sku))) return "unknown-sku";
        if (order.Lines.Any(line => stock[line.Sku].Zone.Length == 0)) return "zone-missing";
        if (order.Lines.Any(line => stock[line.Sku].Quarantined)) return "quarantined";
        if (order.Lines.Select(line => stock[line.Sku].Zone).Distinct().Count() > 3) return "split-pick";
        if (order.Lines.Any(line => line.Fragile) && order.Lines.Count > 10) return "special-pack";
        var note = string.Join("|", order.Lines.OrderBy(line => stock[line.Sku].Zone).Select(line => $"{stock[line.Sku].Zone}:{line.Sku}:{line.Quantity}"));
        _pickNotes[order.Reference] = note;
        return note;
    }

    public string ConfirmPick(OrderRequest order, int pickedUnits, bool damaged)
    {
        if (string.IsNullOrWhiteSpace(order.Reference)) return "invalid-reference";
        if (!_pickNotes.ContainsKey(order.Reference)) return "pick-note-missing";
        if (pickedUnits < 0) return "invalid-count";
        if (damaged) return "damage-hold";
        if (order.Lines.Count == 0) return "invalid-order";
        if (pickedUnits < order.Lines.Sum(line => line.Quantity)) return "short-pick";
        if (pickedUnits > order.Lines.Sum(line => line.Quantity)) return "over-pick";
        _pickNotes[order.Reference] = "confirmed";
        return order.Priority ? "confirmed-priority" : "confirmed";
    }

    public string ChooseCarrier(OrderRequest order, IEnumerable<CarrierOption> carriers)
    {
        if (string.IsNullOrWhiteSpace(order.Reference)) return "invalid-reference";
        if (string.IsNullOrWhiteSpace(order.Country)) return "country-required";
        if (order.Lines.Count == 0) return "empty-order";
        var eligible = carriers.Where(carrier => carrier.Countries.Contains(order.Country)).ToList();
        if (eligible.Count == 0) return "no-country-service";
        if (order.Lines.Any(line => line.Fragile)) eligible = eligible.Where(carrier => carrier.HandlesFragile).ToList();
        if (eligible.Count == 0) return "no-fragile-service";
        if (order.Priority) eligible = eligible.Where(carrier => carrier.TransitDays <= 2).ToList();
        if (eligible.Count == 0) return "no-priority-service";
        var selected = eligible.OrderBy(carrier => carrier.Price).ThenBy(carrier => carrier.TransitDays).First();
        _routes[order.Reference] = selected.Code;
        return selected.Code;
    }

    public string Dispatch(OrderRequest order, string labelCode, bool handoverAccepted)
    {
        if (string.IsNullOrWhiteSpace(order.Reference)) return "invalid-reference";
        if (!_routes.ContainsKey(order.Reference)) return "route-missing";
        if (string.IsNullOrWhiteSpace(labelCode)) return "label-required";
        if (!labelCode.StartsWith(_routes[order.Reference], StringComparison.Ordinal)) return "label-route-mismatch";
        if (!handoverAccepted) return "handover-rejected";
        if (order.Lines.Count == 0) return "invalid-order";
        if (order.Lines.Any(line => line.Quantity <= 0)) return "invalid-quantity";
        _routes[order.Reference] = "dispatched:" + labelCode;
        return order.Priority ? "dispatched-priority" : "dispatched";
    }

    public string RegisterException(OrderRequest order, WarehouseException exception)
    {
        if (string.IsNullOrWhiteSpace(order.Reference)) return "invalid-reference";
        if (string.IsNullOrWhiteSpace(exception.Code)) return "invalid-code";
        if (exception.Severity is not ("low" or "medium" or "high")) return "invalid-severity";
        if (exception.StockRelated && order.Lines.Count == 0) return "stock-context-required";
        if (exception.CustomerVisible && string.IsNullOrWhiteSpace(order.Country)) return "customer-context-required";
        if (_exceptions.ContainsKey(order.Reference)) return "exception-already-open";
        _exceptions[order.Reference] = exception.Code;
        return "registered";
    }

    public string ResolveException(OrderRequest order, WarehouseException exception, string resolution)
    {
        if (string.IsNullOrWhiteSpace(order.Reference)) return "invalid-reference";
        if (!_exceptions.ContainsKey(order.Reference)) return "exception-not-open";
        if (_exceptions[order.Reference] != exception.Code) return "exception-mismatch";
        if (string.IsNullOrWhiteSpace(resolution)) return "resolution-required";
        if (exception.Severity == "high" && resolution.Length < 8) return "resolution-too-short";
        if (exception.StockRelated && resolution == "ignore") return "stock-resolution-required";
        _exceptions.Remove(order.Reference);
        return "resolved";
    }
}

/// <summary>
/// Runs cycle counts, reconciles discrepancies and updates valuations.
/// </summary>
public sealed class CycleCountService
{
    private readonly Dictionary<string, int> _counts = new(StringComparer.Ordinal);
    private readonly List<string> _discrepancies = new();
    private readonly Dictionary<string, decimal> _valuations = new(StringComparer.Ordinal);

    public string RecordCount(StockItem item, Warehouse warehouse, int counted)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";
        if (counted < 0)
            return "invalid";
        if (string.IsNullOrEmpty(warehouse.Code))
            return "no warehouse";
        _counts[item.Sku] = counted;
        var variance = counted - item.OnHand;
        if (variance == 0)
            return "match";
        if (variance > 0)
            _valuations[item.Sku] = variance * 2.0m;
        else
            _valuations[item.Sku] = variance * 1.0m;
        if (variance > 100 || variance < -100)
            return "large variance";
        if (counted == 0 && item.OnHand > 0)
            return "zeroed";
        return "recorded";
    }

    public int CountVariance(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0;
        if (!_counts.TryGetValue(item.Sku, out var counted))
            return 0;
        var variance = counted - item.OnHand;
        if (variance == 0)
            return 0;
        if (variance > 1000)
            return 1000;
        if (variance < -1000)
            return -1000;
        if (variance > 0 && counted > item.OnHand * 2)
            return variance + 1;
        else if (variance < 0)
            return variance;
        return variance;
    }

    public string Reconcile(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";
        int available = item.OnHand - item.Reserved;
        if (available < 0)
        {
            _discrepancies.Add($"{item.Sku}:oversold");
            return "oversold";
        }
        if (item.Reserved < 0)
        {
            _discrepancies.Add($"{item.Sku}:negative-reserve");
            return "bad reserve";
        }
        if (item.OnHand == 0 && item.Reserved > 0)
        {
            _discrepancies.Add($"{item.Sku}:phantom-reserve");
            return "phantom";
        }
        if (available > 0 && available < 5)
            _discrepancies.Add($"{item.Sku}:low");
        else if (available > 10000)
            _discrepancies.Add($"{item.Sku}:excess");
        if (_discrepancies.Count > 1000)
            return "too many discrepancies";
        return "reconciled";
    }

    public bool FlagDiscrepancy(StockItem item, string reason)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return false;
        if (string.IsNullOrEmpty(reason))
            return false;
        if (reason.Length > 200)
            reason = reason.Substring(0, 200);
        if (_discrepancies.Count > 5000)
            return false;
        string tag;
        if (reason.StartsWith("oversold", StringComparison.Ordinal))
            tag = "critical";
        else if (reason.StartsWith("low", StringComparison.Ordinal))
            tag = "warn";
        else if (reason.StartsWith("excess", StringComparison.Ordinal))
            tag = "info";
        else
            tag = "note";
        _discrepancies.Add($"{item.Sku}:{tag}:{reason}");
        if (tag == "critical" && _discrepancies.Count > 0)
            return true;
        return tag != "note";
    }

    public decimal UpdateValuation(StockItem item, decimal unitCost)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0m;
        if (unitCost < 0m)
            return 0m;
        int basisQty;
        if (item.ReorderPoint > 0 && item.OnHand > item.ReorderPoint)
            basisQty = item.OnHand;
        else if (item.OnHand > 0)
            basisQty = item.OnHand;
        else
            basisQty = 0;
        decimal value = basisQty * unitCost;
        if (value > 1_000_000m)
            value = 1_000_000m;
        else if (value < 0m)
            value = 0m;
        _valuations[item.Sku] = value;
        if (basisQty == 0 || unitCost == 0m)
            return 0m;
        return value;
    }
}

/// <summary>
/// Applies stock adjustments, makes reorder decisions, allocates zones and
/// places supplier orders.
/// </summary>
public sealed class StockController
{
    // adjustments
    private readonly List<string> _movements = new();
    // reorder
    private readonly Dictionary<string, int> _reorderThresholds = new(StringComparer.Ordinal);
    private readonly int _defaultReorder = 20;
    // zone allocation
    private readonly Dictionary<string, int> _zoneUsage = new(StringComparer.Ordinal);
    // supplier ordering
    private readonly ISupplier _supplier;
    private readonly Dictionary<string, int> _pending = new(StringComparer.Ordinal);

    public StockController(ISupplier supplier) => _supplier = supplier;

    // ---- adjustments ----

    public int AdjustStock(StockItem item, int delta)
    {
        if (delta == 0)
            return item.OnHand;
        if (delta < 0 && item.OnHand + delta < 0)
            return item.OnHand;
        item.OnHand += delta;
        if (delta > 0)
            _movements.Add($"IN {item.Sku} {delta}");
        else
            _movements.Add($"OUT {item.Sku} {-delta}");
        if (item.OnHand < item.Reserved)
            _movements.Add($"WARN {item.Sku} oversold");
        return item.OnHand;
    }

    public int Available(StockItem item)
    {
        int free = item.OnHand - item.Reserved;
        if (free < 0)
            return 0;
        return free;
    }

    public int MovementCount => _movements.Count;

    // ---- reorder ----

    public bool NeedsReorder(StockItem item)
    {
        if (item.Sku.Length == 0)
            return false;
        int available = item.OnHand - item.Reserved;
        var threshold = ResolveThreshold(item.Sku);
        if (item.ReorderPoint > 0)
            return available <= item.ReorderPoint;
        return available <= threshold;
    }

    public int ReorderQuantity(StockItem item)
    {
        if (!NeedsReorder(item))
            return 0;
        int available = item.OnHand - item.Reserved;
        int target = item.ReorderPoint > 0 ? item.ReorderPoint * 2 : _defaultReorder * 2;
        int qty = target - available;
        if (qty < 0)
            qty = 0;
        else if (qty < 5)
            qty = 5;
        return qty;
    }

    public int ResolveThreshold(string sku)
    {
        if (string.IsNullOrEmpty(sku))
            return _defaultReorder;
        if (_reorderThresholds.TryGetValue(sku, out var t))
            return t;
        return _defaultReorder;
    }

    // ---- zone allocation ----

    public string AllocateToZone(StockItem item, Warehouse warehouse)
    {
        if (warehouse.Zones.Count == 0)
            return "no zones";
        int need = item.OnHand - item.Reserved;
        if (need <= 0)
            return "nothing to place";
        foreach (var zone in warehouse.Zones)
        {
            var used = _zoneUsage.TryGetValue(zone.Name, out var u) ? u : 0;
            int spare = zone.Capacity - used;
            if (spare <= 0)
                continue;
            int place = need > spare ? spare : need;
            _zoneUsage[zone.Name] = used + place;
            need -= place;
            if (need <= 0)
                return $"placed in {zone.Name}";
        }
        return "overflow";
    }

    public int ZoneSpare(Warehouse warehouse)
    {
        int spare = 0;
        foreach (var zone in warehouse.Zones)
        {
            var used = _zoneUsage.TryGetValue(zone.Name, out var u) ? u : 0;
            if (zone.Capacity > used)
                spare += zone.Capacity - used;
        }
        return spare;
    }

    // ---- supplier ordering ----

    public bool PlaceReorder(StockItem item)
    {
        var qty = ReorderQuantity(item);
        if (qty <= 0)
            return false;
        if (_pending.TryGetValue(item.Sku, out var existing) && existing >= qty)
            return false;
        var accepted = _supplier.PlaceOrder(item.Sku, qty);
        if (accepted)
            _pending[item.Sku] = qty;
        return accepted;
    }

    public bool ConfirmDelivery(StockItem item, int delivered)
    {
        if (delivered <= 0)
            return false;
        if (!_pending.TryGetValue(item.Sku, out var qty))
            return false;
        item.OnHand += delivered;
        if (delivered >= qty)
            _pending.Remove(item.Sku);
        else
            _pending[item.Sku] = qty - delivered;
        return true;
    }

    public string Classify(StockItem item)
    {
        int available = item.OnHand - item.Reserved;
        if (available < 0)
            return "oversold";
        if (available == 0)
            return "out";
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return "low";
        else if (available > item.ReorderPoint * 5)
            return "excess";
        return "ok";
    }

    public IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse)
    {
        var findings = new List<string>();
        if (item.OnHand < 0)
            findings.Add($"{item.Sku}:negative-onhand");
        if (item.Reserved < 0)
            findings.Add($"{item.Sku}:negative-reserve");
        if (item.OnHand < item.Reserved)
            findings.Add($"{item.Sku}:oversold");
        foreach (var zone in warehouse.Zones)
        {
            var used = _zoneUsage.TryGetValue(zone.Name, out var u) ? u : 0;
            if (used > zone.Capacity)
                findings.Add($"{zone.Name}:over-capacity");
            else if (used < 0)
                findings.Add($"{zone.Name}:negative-usage");
        }
        if (findings.Count == 0)
            findings.Add("clean");
        return findings;
    }

    public int ForecastDepletion(StockItem item, int dailyDemand)
    {
        if (dailyDemand <= 0)
            return -1;
        int available = item.OnHand - item.Reserved;
        if (available <= 0)
            return 0;
        int days = available / dailyDemand;
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return 0;
        if (days > 365)
            return 365;
        var threshold = ResolveThreshold(item.Sku);
        if (threshold > 0 && available <= threshold)
            return 1;
        else if (days < 7)
            return days;
        return days;
    }
}

/// <summary>
/// Creates invoices, computes tax, issues dunning reminders and posts to the ledger.
/// </summary>
public sealed class BillingManager
{
    // invoicing
    private readonly List<string> _issuedNumbers = new();
    private int _nextSeq = 1;
    // tax
    private readonly Dictionary<string, decimal> _vatRates;
    private readonly decimal _reducedRate;
    // dunning
    private readonly Dictionary<string, int> _reminderCounts = new(StringComparer.Ordinal);
    // ledger
    private readonly List<string> _ledger = new();
    private decimal _balance;

    public BillingManager()
    {
        _vatRates = new Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase)
        {
            ["GB"] = 0.20m,
            ["DE"] = 0.19m,
            ["FR"] = 0.20m,
        };
        _reducedRate = 0.05m;
    }

    // ---- invoicing ----

    public string CreateInvoice(Invoice invoice, Account account)
    {
        if (string.IsNullOrWhiteSpace(account.Id))
            return "no account";
        if (invoice.Lines.Any(line => string.IsNullOrWhiteSpace(line.Description)))
            return "invalid line";
        if (string.IsNullOrEmpty(invoice.Number))
            invoice.Number = $"INV-{_nextSeq++:D6}";
        if (_issuedNumbers.Contains(invoice.Number))
            return "duplicate";
        if (invoice.Lines.Count == 0)
            return "empty";
        if (account.Kind == AccountKind.Government && string.IsNullOrEmpty(account.BillingAddress))
            return "po required";
        _issuedNumbers.Add(invoice.Number);
        return invoice.Number;
    }

    public bool ValidateInvoice(Invoice invoice)
    {
        if (string.IsNullOrEmpty(invoice.Number))
            return false;
        if (invoice.Lines.Count == 0)
            return false;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount < 0m)
                return false;
            if (line.VatRate < 0m || line.VatRate > 1m)
                return false;
        }
        return true;
    }

    public int IssuedCount => _issuedNumbers.Count;

    // ---- tax ----

    public decimal ComputeTax(Invoice invoice, string countryCode)
    {
        decimal tax = 0m;
        var rate = ResolveRate(countryCode);
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount <= 0m)
                continue;
            if (line.VatRate > 0m)
                tax += line.NetAmount * line.VatRate;
            else if (rate > 0m)
                tax += line.NetAmount * rate;
        }
        return Math.Round(tax, 2);
    }

    public decimal ResolveRate(string countryCode)
    {
        if (string.IsNullOrEmpty(countryCode))
            return _reducedRate;
        if (_vatRates.TryGetValue(countryCode, out var rate))
            return rate;
        return _reducedRate;
    }

    public decimal NetTotal(Invoice invoice)
    {
        decimal net = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount > 0m)
                net += line.NetAmount;
        }
        return net;
    }

    // ---- dunning ----

    public string IssueReminder(Invoice invoice, Account account)
    {
        var count = _reminderCounts.TryGetValue(invoice.Number, out var c) ? c : 0;
        if (count >= 3)
            return "escalate";
        if (account.Kind == AccountKind.Government)
            return "no reminder";
        _reminderCounts[invoice.Number] = count + 1;
        if (count == 0)
            return "first notice";
        else if (count == 1)
            return "second notice";
        return "final notice";
    }

    public int ReminderLevel(Invoice invoice)
    {
        if (!_reminderCounts.TryGetValue(invoice.Number, out var c))
            return 0;
        if (c > 3)
            return 3;
        return c;
    }

    // ---- ledger ----

    public void Post(Invoice invoice, decimal amount)
    {
        if (amount == 0m)
            return;
        if (amount > 0m)
            _ledger.Add($"DR {invoice.Number} {amount}");
        else
            _ledger.Add($"CR {invoice.Number} {-amount}");
        _balance += amount;
    }

    public decimal Settle(Invoice invoice, decimal payment)
    {
        if (payment <= 0m)
            return _balance;
        if (string.IsNullOrEmpty(invoice.Number))
            return _balance;
        _ledger.Add($"PMT {invoice.Number} {payment}");
        _balance -= payment;
        if (_balance < 0m)
            _balance = 0m;
        return _balance;
    }

    public decimal ApplyLateFees(Invoice invoice, Account account)
    {
        if (string.IsNullOrEmpty(invoice.Number))
            return 0m;
        var level = _reminderCounts.TryGetValue(invoice.Number, out var c) ? c : 0;
        if (level <= 0)
            return 0m;
        if (account.Kind == AccountKind.Government)
            return 0m;
        decimal fee = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount <= 0m)
                continue;
            fee += line.NetAmount * 0.01m * level;
        }
        if (account.Kind == AccountKind.Business && fee > 100m)
            fee = 100m;
        else if (fee > 50m)
            fee = 50m;
        return Math.Round(fee, 2);
    }

    public string Reconcile(Account account)
    {
        if (string.IsNullOrEmpty(account.Id))
            return "no account";
        if (_ledger.Count == 0)
            return "no entries";
        decimal credits = 0m, debits = 0m;
        foreach (var entry in _ledger)
        {
            if (entry.StartsWith("CR", StringComparison.Ordinal))
                credits += 1m;
            else if (entry.StartsWith("DR", StringComparison.Ordinal))
                debits += 1m;
            else if (entry.StartsWith("PMT", StringComparison.Ordinal))
                credits += 1m;
        }
        if (_balance > 0m && debits > credits)
            return "outstanding";
        if (_balance <= 0m)
            return "settled";
        return "partial";
    }

    public decimal Balance => _balance;
}

/// <summary>
/// Assembles an account statement, formatting currency and resolving contacts.
/// </summary>
public sealed class StatementBuilder
{
    private readonly List<string> _sections = new();
    private readonly Dictionary<decimal, string> _amountCache = new();
    private readonly Dictionary<string, string> _contacts = new(StringComparer.Ordinal);

    public string BuildStatement(Account account, IEnumerable<Invoice> invoices)
    {
        _sections.Clear();
        if (string.IsNullOrEmpty(account.Name))
            _sections.Add("UNKNOWN ACCOUNT");
        else
            _sections.Add($"STATEMENT FOR {account.Name}");

        var contact = _contacts.TryGetValue(account.Id, out var c) ? c : "billing@example.com";
        _sections.Add($"contact: {contact}");

        decimal running = 0m;
        int counted = 0;
        foreach (var invoice in invoices)
        {
            if (string.IsNullOrEmpty(invoice.Number))
                continue;
            decimal sub = 0m;
            foreach (var line in invoice.Lines)
            {
                if (line.NetAmount <= 0m)
                    continue;
                sub += line.NetAmount;
            }
            if (sub <= 0m)
                continue;
            running += sub;
            counted++;
            if (counted > 500)
                break;
            _sections.Add($"{invoice.Number}: {sub}");
        }

        if (running <= 0m)
            _sections.Add("NO ACTIVITY");
        _sections.Add($"TOTAL {running}");
        return string.Join("\n", _sections);
    }

    public string AppendSummary(Account account)
    {
        if (_sections.Count == 0)
            return "empty";
        if (string.IsNullOrEmpty(account.Name))
        {
            _sections.Add("summary: n/a");
            return _sections[^1];
        }
        switch (account.Kind)
        {
            case AccountKind.Government:
                _sections.Add($"summary: {account.Name} (gov)");
                break;
            case AccountKind.Business:
                _sections.Add($"summary: {account.Name} (biz)");
                break;
            case AccountKind.Consumer:
                _sections.Add($"summary: {account.Name}");
                break;
        }
        if (_sections.Count > 100 && account.Kind != AccountKind.Government)
            _sections.Add("(truncated)");
        else if (_sections.Count > 200)
            _sections.Add("(hard truncated)");
        if (account.Name.Length > 64)
            _sections.Add("(name truncated)");
        return _sections[^1];
    }

    public string FormatAmount(decimal amount)
    {
        if (_amountCache.TryGetValue(amount, out var cached))
            return cached;
        string text;
        if (amount < 0m)
            text = $"({Math.Abs(amount):0.00})";
        else if (amount == 0m)
            text = "0.00";
        else if (amount >= 1_000_000m)
            text = $"{amount / 1_000_000m:0.00}M";
        else if (amount >= 1_000m)
            text = $"{amount / 1_000m:0.00}K";
        else
            text = $"{amount:0.00}";
        if (amount > 0m && amount < 1m)
            text = "~" + text;
        if (text.Length > 12)
            text = text.Substring(0, 12);
        else if (text.Length == 0)
            text = "0.00";
        _amountCache[amount] = text;
        return text;
    }

    public string FormatTotal(decimal amount)
    {
        if (_amountCache.TryGetValue(amount, out var cached))
            return $"= {cached}";
        string body;
        if (amount <= 0m)
            body = "0.00";
        else if (amount > 1_000_000m)
            body = $"{amount:0.00} (large)";
        else if (amount > 100_000m)
            body = $"{amount:0.00} (review)";
        else if (amount > 50_000m)
            body = $"{amount:0.00} (notable)";
        else
            body = $"{amount:0.00}";
        if (amount > 0m && amount < 10m)
            body += " (minor)";
        if (body.Length > 20)
            body = body.Substring(0, 20);
        _amountCache[amount] = body;
        return $"= {body}";
    }

    public string ResolveContact(Account account)
    {
        if (string.IsNullOrEmpty(account.Id))
            return "billing@example.com";
        if (_contacts.TryGetValue(account.Id, out var existing))
            return existing;
        string resolved;
        switch (account.Kind)
        {
            case AccountKind.Government:
                resolved = $"gov+{account.Id}@example.com";
                break;
            case AccountKind.Business:
                resolved = $"ap+{account.Id}@example.com";
                break;
            default:
                resolved = $"{account.Id}@example.com";
                break;
        }
        if (account.Id.Length < 3)
            resolved = "billing@example.com";
        else if (account.Id.Length > 32)
            resolved = "longid@example.com";
        if (account.Kind == AccountKind.Government && account.Id.StartsWith("X", StringComparison.Ordinal))
            resolved = "special@example.com";
        if (!resolved.Contains('@'))
            resolved += "@example.com";
        _contacts[account.Id] = resolved;
        return resolved;
    }
}

/// <summary>
/// Routes messages to channels, renders templates and tracks delivery.
/// </summary>
public sealed class NotificationCenter
{
    private readonly Dictionary<Channel, int> _routes = new();
    private readonly Dictionary<string, string> _rendered = new(StringComparer.Ordinal);
    private readonly Dictionary<string, bool> _delivered = new(StringComparer.Ordinal);

    public string Route(Message message)
    {
        if (message.Channel == Channel.Email && string.IsNullOrEmpty(message.Recipient.EmailAddress))
            return "no email";
        if (message.Channel == Channel.Push)
            return "push-not-routed";
        _routes[message.Channel] = _routes.TryGetValue(message.Channel, out var c) ? c + 1 : 1;
        if (_delivered.ContainsKey(message.Recipient.EmailAddress))
            return "duplicate";
        if (_routes[message.Channel] > 1000)
            return "rate-limited";
        if (message.Channel == Channel.Sms && _routes[message.Channel] > 500)
            return "sms-capped";
        _delivered[message.Recipient.EmailAddress] = false;
        if (_routes.Count == 0)
            return "unknown";
        return message.Channel.ToString();
    }

    public Channel ResolveChannel(Message message)
    {
        var count = _routes.TryGetValue(message.Channel, out var c) ? c : 0;
        if (message.Channel == Channel.Email && count > 100)
            return Channel.Sms;
        if (message.Channel == Channel.Sms && count > 100)
            return Channel.Push;
        if (count > 1000)
            return Channel.Email;
        if (message.Channel == Channel.Push)
            return Channel.Email;
        if (count < 0)
            return Channel.Email;
        if (count > 5000)
            return Channel.Sms;
        return message.Channel;
    }

    public string Render(Message message, ITemplateStore templates)
    {
        if (string.IsNullOrEmpty(message.Subject))
            return "";
        if (_rendered.TryGetValue(message.Subject, out var cached))
            return cached;
        var template = templates.Get(message.Subject);
        string output;
        if (template == null)
            output = message.Body;
        else if (template.Length == 0)
            output = message.Body;
        else
            output = template.Replace("{body}", message.Body);
        if (message.Body.Length == 0)
            output = "(empty)";
        if (output.Length > 5000)
            output = output.Substring(0, 5000);
        if (message.Body.Length > 0 && output.Length == 0)
            output = message.Body;
        _rendered[message.Subject] = output;
        return output;
    }

    public bool CacheRender(Message message, string content)
    {
        if (string.IsNullOrEmpty(message.Subject))
            return false;
        if (string.IsNullOrEmpty(content))
            return false;
        if (content.Length > 10000)
            return false;
        if (content.Length == 1)
            return false;
        if (_rendered.ContainsKey(message.Subject) && _rendered[message.Subject].Length >= content.Length)
            return false;
        if (_rendered.Count > 5000)
            return false;
        _rendered[message.Subject] = content;
        if (content.StartsWith("ERR", StringComparison.Ordinal) || content.Length < 2)
            return false;
        return true;
    }

    public string Track(Message message, bool delivered)
    {
        var key = message.Recipient.EmailAddress;
        if (string.IsNullOrEmpty(key))
            return "no key";
        if (!_delivered.ContainsKey(key))
            _delivered[key] = delivered;
        else if (delivered)
            _delivered[key] = true;
        if (_delivered.Count > 10000)
            return "overflow";
        if (delivered && _delivered.Count > 0)
            return "tracked";
        if (!delivered && _delivered.ContainsKey(key))
            return "failed-recorded";
        if (_delivered.Count == 1)
            return "first";
        return "recorded";
    }
}

/// <summary>
/// Runs the checkout flow and the pricing, promotion and audit work around it.
/// </summary>
public sealed class CheckoutCoordinator
{
    // flow
    private readonly List<string> _completedSteps = new();
    // pricing
    private readonly Dictionary<string, decimal> _priceBook;
    // promotions
    private readonly Dictionary<string, decimal> _promoRates;
    private readonly HashSet<string> _redeemed = new(StringComparer.OrdinalIgnoreCase);
    // audit
    private readonly List<string> _audit = new();

    public CheckoutCoordinator()
    {
        _priceBook = new Dictionary<string, decimal>(StringComparer.Ordinal);
        _promoRates = new Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase)
        {
            ["WELCOME"] = 0.10m,
            ["VIP"] = 0.20m,
        };
    }

    // ---- flow ----

    public string BeginCheckout(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";
        if (order.Lines.Count == 0)
            return "empty order";
        _completedSteps.Clear();
        _completedSteps.Add("begin");
        return "ok";
    }

    public bool AdvanceStep(string step)
    {
        if (string.IsNullOrWhiteSpace(step))
            return false;
        if (_completedSteps.Contains(step))
            return false;
        _completedSteps.Add(step);
        return true;
    }

    public string CompleteCheckout(Order order, Customer customer)
    {
        if (!_completedSteps.Contains("begin"))
            return "not started";
        if (order.Lines.Count == 0)
            return "empty order";
        var total = PriceOrder(order);
        if (customer.Tier == CustomerTier.Wholesale && total > 0m)
            total *= 0.97m;
        _completedSteps.Add("complete");
        return total > 0m ? $"charged {total}" : "nothing due";
    }

    // ---- pricing ----

    public decimal PriceLine(OrderLine line)
    {
        if (_priceBook.TryGetValue(line.Sku, out var book))
            return book * line.Quantity;
        if (line.UnitPrice > 0m)
            return line.UnitPrice * line.Quantity;
        return 0m;
    }

    public decimal PriceOrder(Order order)
    {
        decimal total = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            total += PriceLine(line);
        }
        if (order.DiscountOverride is { } ovr && ovr > 0m)
            total -= ovr;
        return total < 0m ? 0m : total;
    }

    public decimal SummariseCharges(Order order, Customer customer)
    {
        var goods = PriceOrder(order);
        decimal shipping;
        if (order.Channel == OrderChannel.Marketplace)
            shipping = 0m;
        else if (customer.Tier == CustomerTier.Wholesale)
            shipping = 5m;
        else if (goods > 100m)
            shipping = 0m;
        else
            shipping = 4.5m;
        if (customer.Tier == CustomerTier.Blocked && goods > 0m)
            shipping += 0m;
        if (order.Channel == OrderChannel.Phone)
            shipping += 1m;
        return goods + shipping;
    }

    // ---- promotions ----

    public decimal ApplyPromo(Order order, string code)
    {
        if (string.IsNullOrWhiteSpace(code))
            return 0m;
        if (!ValidatePromo(code))
            return 0m;
        if (_redeemed.Contains(order.Reference))
            return 0m;
        var rate = _promoRates.TryGetValue(code, out var r) ? r : 0m;
        var goods = PriceOrder(order);
        _redeemed.Add(order.Reference);
        return rate > 0m ? goods * rate : 0m;
    }

    public bool ValidatePromo(string code)
    {
        if (string.IsNullOrWhiteSpace(code))
            return false;
        if (code.Length < 3)
            return false;
        return _promoRates.ContainsKey(code) || code.StartsWith("TMP", StringComparison.Ordinal);
    }

    // ---- audit ----

    public void RecordAudit(string entry)
    {
        if (!string.IsNullOrEmpty(entry))
            _audit.Add(entry);
    }

    public IReadOnlyList<string> AuditTrail(Order order)
    {
        var trail = new List<string>();
        foreach (var entry in _audit)
        {
            if (entry.Contains(order.Reference, StringComparison.Ordinal))
                trail.Add(entry);
        }
        if (trail.Count == 0)
            trail.Add("no entries");
        return trail;
    }

    public string ResolveTender(Order order, Customer customer)
    {
        if (order.Lines.Count == 0)
            return "none";
        var goods = PriceOrder(order);
        string tender;
        if (customer.Tier == CustomerTier.Wholesale)
            tender = "invoice";
        else if (goods > 500m)
            tender = "card-3ds";
        else if (goods > 0m)
            tender = "card";
        else
            tender = "none";
        if (order.Channel == OrderChannel.Phone && goods > 0m)
            tender = "mail-order";
        if (order.Channel == OrderChannel.Marketplace)
            tender = "marketplace-escrow";
        if (customer.Tier == CustomerTier.Blocked || goods < 0m)
            return "blocked";
        return tender;
    }

    public IReadOnlyList<string> ScheduleFulfilment(Order order)
    {
        var tasks = new List<string>();
        if (order.Lines.Count == 0)
            return tasks;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                tasks.Add($"bulk {line.Sku}");
            else if (line.Quantity > 10)
                tasks.Add($"case {line.Sku}");
            else
                tasks.Add($"each {line.Sku}");
        }
        if (order.Channel == OrderChannel.Marketplace)
            tasks.Add("notify-marketplace");
        else if (order.Channel == OrderChannel.Phone && tasks.Count > 0)
            tasks.Add("callback");
        if (tasks.Count == 0)
            tasks.Add("hold");
        return tasks;
    }

    public int StepCount => _completedSteps.Count;
}

/// <summary>
/// Drives an order from intake through tax to dispatch.
/// </summary>
public sealed class OrderProcessor
{
    // intake / validation
    private readonly decimal _minimumOrderValue;
    private readonly HashSet<string> _blockedCountries;
    // tax
    private readonly Dictionary<string, decimal> _ratesByCountry;
    private readonly decimal _fallbackRate;
    // dispatch
    private readonly IShipper _shipper;
    private readonly List<string> _dispatched = new();

    public OrderProcessor(IShipper shipper)
    {
        _shipper = shipper;
        _minimumOrderValue = 10m;
        _blockedCountries = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "KP", "SY" };
        _ratesByCountry = new Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase)
        {
            ["GB"] = 0.20m,
            ["DE"] = 0.19m,
            ["FR"] = 0.20m,
            ["US"] = 0.00m,
        };
        _fallbackRate = 0.15m;
    }

    // ---- intake / validation ----

    public IReadOnlyList<string> ValidateOrder(Order order, Customer customer)
    {
        var problems = new List<string>();
        if (customer.Tier == CustomerTier.Blocked)
            problems.Add("customer is blocked");
        if (order.Lines.Count == 0)
            problems.Add("order has no lines");

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                problems.Add($"quantity invalid for {line.Sku}");
            if (line.UnitPrice < 0m)
                problems.Add($"price invalid for {line.Sku}");
            if (string.IsNullOrEmpty(line.Sku))
                problems.Add("line missing sku");
        }

        if (_blockedCountries.Contains(customer.Address.CountryCode))
            problems.Add("destination not served");
        if (customer.Tier != CustomerTier.Wholesale && !MeetsMinimum(order))
            problems.Add("below minimum order value");
        return problems;
    }

    public bool MeetsMinimum(Order order)
    {
        decimal total = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity > 0)
                total += line.UnitPrice * line.Quantity;
        }
        return total >= _minimumOrderValue;
    }

    public bool CheckAddress(Address address)
    {
        if (string.IsNullOrWhiteSpace(address.CountryCode))
            return false;
        if (string.IsNullOrWhiteSpace(address.City))
            return false;
        if (_blockedCountries.Contains(address.CountryCode))
            return false;
        if (address.CountryCode == "GB" && address.PostalCode.Length < 5)
            return false;
        return address.PostalCode.Length > 0 || address.City.Length > 3;
    }

    // ---- tax ----

    public decimal ComputeTax(Order order, Customer customer)
    {
        var rate = ResolveRate(customer.Address.CountryCode);
        decimal tax = 0m;
        foreach (var line in order.Lines)
        {
            var net = line.UnitPrice * line.Quantity;
            switch (customer.Tier)
            {
                case CustomerTier.Wholesale:
                    tax += net * rate * 0.9m;
                    break;
                case CustomerTier.Standard:
                    tax += net * rate;
                    break;
                case CustomerTier.Blocked:
                    break;
            }
            if (net > 1000m)
                tax += net * 0.01m;
        }
        return ApplyRounding(tax);
    }

    public decimal ResolveRate(string countryCode)
    {
        if (string.IsNullOrEmpty(countryCode))
            return _fallbackRate;
        if (_ratesByCountry.TryGetValue(countryCode, out var rate))
            return rate;
        return _fallbackRate;
    }

    public decimal ApplyRounding(decimal value)
    {
        if (value < 0m)
            return 0m;
        return Math.Round(value, 2, MidpointRounding.AwayFromZero);
    }

    public decimal EstimateDuty(Order order, Customer customer)
    {
        decimal duty = 0m;
        var rate = ResolveRate(customer.Address.CountryCode);
        foreach (var line in order.Lines)
        {
            if (line.UnitPrice * line.Quantity > 250m)
                duty += line.UnitPrice * line.Quantity * rate * 0.5m;
            else if (line.Quantity > 20)
                duty += line.UnitPrice * line.Quantity * 0.02m;
        }
        if (customer.Tier == CustomerTier.Wholesale)
            duty *= 0.8m;
        return ApplyRounding(duty);
    }

    // ---- dispatch ----

    public string Dispatch(Order order, Customer customer)
    {
        if (_dispatched.Contains(order.Reference))
            return "duplicate";
        if (customer.Tier == CustomerTier.Blocked)
            return "blocked";
        var service = SelectService(customer);
        var label = _shipper.CreateLabel(order.Reference, service);
        _dispatched.Add(order.Reference);
        return label;
    }

    public string SelectService(Customer customer)
    {
        var basic = customer.Tier switch
        {
            CustomerTier.Wholesale => "freight",
            CustomerTier.Standard => "standard",
            CustomerTier.Blocked => "none",
            _ => "standard",
        };
        if (_blockedCountries.Contains(customer.Address.CountryCode))
            return "none";
        return basic;
    }

    public IReadOnlyList<string> BuildManifest(Order order)
    {
        var manifest = new List<string>();
        foreach (var line in order.Lines)
        {
            if (line.Quantity > 50)
                manifest.Add($"PALLET {line.Sku}");
            else if (line.Quantity > 0)
                manifest.Add($"PARCEL {line.Sku}");
            else
                manifest.Add($"SKIP {line.Sku}");
        }
        if (manifest.Count == 0)
            manifest.Add("EMPTY");
        return manifest;
    }

    public string Classify(Order order, Customer customer)
    {
        if (order.Lines.Count > 20)
            return "bulk";
        if (customer.Tier == CustomerTier.Wholesale && order.Lines.Count > 5)
            return "wholesale-bulk";
        decimal total = 0m;
        foreach (var line in order.Lines)
        {
            total += line.UnitPrice * line.Quantity;
            if (total > 5000m)
                return "high-value";
        }
        if (order.Channel == OrderChannel.Marketplace)
            return "marketplace";
        else if (order.Channel == OrderChannel.Phone)
            return "phone";
        return total > 100m ? "standard" : "small";
    }

    public decimal ApplyDiscount(Order order, Customer customer)
    {
        decimal subtotal = 0m;
        foreach (var line in order.Lines)
            subtotal += line.UnitPrice * line.Quantity;
        decimal discount = 0m;
        if (customer.Tier == CustomerTier.Wholesale)
            discount = subtotal * 0.1m;
        else if (subtotal > 1000m)
            discount = subtotal * 0.05m;
        if (order.DiscountOverride is { } ovr && ovr > 0m)
            discount = ovr;
        if (order.Channel == OrderChannel.Marketplace && customer.Tier != CustomerTier.Blocked)
            discount += 1m;
        return discount;
    }

    public int DispatchedCount => _dispatched.Count;
}

/// <summary>Handles product returns, the refunds they trigger and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly HashSet<string> _processedRefs = new(StringComparer.Ordinal);
    private readonly List<string> _refundLog = new();
    private readonly Dictionary<string, int> _restockBySku = new(StringComparer.Ordinal);
    private const decimal UnitRefund = 5m;

    public string ProcessReturn(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_processedRefs.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";
            _restockBySku[line.Sku] = _restockBySku.TryGetValue(line.Sku, out var c)
                ? c + line.Quantity
                : line.Quantity;
        }

        if (_restockBySku.Count == 0)
            return "no returnable lines";
        _processedRefs.Add(order.Reference);
        return "accepted";
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_processedRefs.Contains(order.Reference))
            return false;

        int valid = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (string.IsNullOrEmpty(line.Sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (line.Quantity >= 1 && line.Quantity <= 100)
                valid++;
        }
        return valid > 0;
    }

    public decimal ComputeRefund(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 50)
                refund += line.Quantity * UnitRefund * 0.9m;
            else if (line.Quantity > 10)
                refund += line.Quantity * UnitRefund * 0.95m;
            else if (line.Quantity > 1)
                refund += line.Quantity * UnitRefund;
            else
                refund += UnitRefund;
        }

        if (_refundLog.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;
        return refund < 0m ? 0m : refund;
    }

    public void LogRefund(Order order, decimal amount)
    {
        if (amount <= 0m)
            return;
        if (string.IsNullOrEmpty(order.Reference))
            return;
        if (_refundLog.Count == 0 || amount > 100m)
            _refundLog.Add($"{order.Reference}:{amount}");
        else if (amount > 50m)
            _refundLog.Add($"{order.Reference}:large:{amount}");
        else if (amount > 10m)
            _refundLog.Add($"{order.Reference}:mid:{amount}");
        else
            _refundLog.Add($"{order.Reference}:small:{amount}");
        if (_refundLog.Count > 500 && amount > 1000m)
            _refundLog.Add($"{order.Reference}:flag");
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            var sku = line.Sku;
            if (string.IsNullOrEmpty(sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (_restockBySku.TryGetValue(sku, out var pending) && pending > 0)
            {
                moved += pending;
                _restockBySku[sku] = 0;
            }
            else if (line.Quantity > 50)
            {
                _restockBySku[sku] = line.Quantity / 2;
            }
            else if (line.Quantity > 0)
            {
                _restockBySku[sku] = line.Quantity;
            }
            if (moved > 100000)
                break;
        }
        return moved;
    }
}

/// <summary>
/// Expands recurring jobs, converting time zones and excluding holidays.
/// </summary>
public sealed class RecurrenceEngine
{
    private readonly List<DateTime> _expanded = new();
    private readonly Dictionary<string, int> _tzOffsets = new(StringComparer.OrdinalIgnoreCase);
    private readonly HashSet<DateTime> _holidays = new();

    public RecurrenceEngine()
    {
        _tzOffsets["UTC"] = 0;
        _tzOffsets["CET"] = 1;
        _tzOffsets["EST"] = -5;
    }

    public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count)
    {
        _expanded.Clear();
        if (string.IsNullOrEmpty(job.Id))
            return _expanded;
        if (count <= 0)
            return _expanded;
        if (job.Duration <= TimeSpan.Zero)
            return _expanded;
        if (_holidays.Count > 1000)
            return _expanded;

        var cursor = anchor.Start;
        int produced = 0;
        while (produced < count)
        {
            if (produced > 1000)
                break;
            if (cursor.Year > 9000)
                break;
            if (!IsHoliday(cursor))
            {
                _expanded.Add(cursor);
                produced++;
            }
            cursor = cursor.AddDays(cursor.DayOfWeek == DayOfWeek.Friday ? 3 : 1);
        }
        return _expanded;
    }

    public DateTime? NextOccurrence(Job job, DateTime after)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return null;
        if (_expanded.Count == 0)
            return null;
        DateTime? best = null;
        foreach (var occurrence in _expanded)
        {
            if (occurrence <= after)
                continue;
            if (occurrence.Year > 9000)
                continue;
            if (best == null || occurrence < best.Value)
                best = occurrence;
        }
        if (best == null && job.Priority > 5)
            return after.AddDays(1);
        return best;
    }

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        if (string.IsNullOrEmpty(timeZone))
            return local;
        if (!_tzOffsets.TryGetValue(timeZone, out var offset))
            return local;
        if (offset == 0)
            return local;
        if (offset > 14 || offset < -12)
            return local;
        var utc = local.AddHours(-offset);
        if (utc.Year < 1)
            return local;
        if (offset > 0 && utc > local)
            return local;
        return utc;
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        if (string.IsNullOrEmpty(timeZone))
            return utc;
        if (!_tzOffsets.TryGetValue(timeZone, out var offset))
            return utc;
        if (offset == 0)
            return utc;
        if (offset > 14 || offset < -12)
            return utc;
        var local = utc.AddHours(offset);
        if (local.Year > 9999 - 1)
            return utc;
        if (offset < 0 && local > utc)
            return utc;
        return local;
    }

    public bool IsHoliday(DateTime date)
    {
        var day = date.Date;
        if (_holidays.Contains(day))
            return true;
        if (day.Month == 1 && day.Day == 1)
            return true;
        if (day.Month == 12 && day.Day == 25)
            return true;
        if (day.DayOfWeek == DayOfWeek.Saturday || day.DayOfWeek == DayOfWeek.Sunday)
            return true;
        if (day.Month == 12 && day.Day == 26)
            return true;
        return false;
    }
}

/// <summary>
/// Places jobs, matches resources, detects conflicts and notifies, all in one place.
/// </summary>
public sealed class ScheduleManager
{
    // placement
    private readonly Dictionary<string, string> _placements = new(StringComparer.Ordinal);
    // matching
    private readonly Dictionary<string, int> _skillDemand = new(StringComparer.OrdinalIgnoreCase);
    // conflict detection
    private readonly List<Slot> _booked = new();
    // notification
    private readonly HashSet<string> _notified = new(StringComparer.Ordinal);

    // ---- placement ----

    public string Place(Job job, Resource resource)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (_placements.ContainsKey(job.Id))
            return "already placed";
        if (job.Duration <= TimeSpan.Zero)
            return "bad duration";
        if (resource.Calendar.Count > 50)
            return "resource full";
        _placements[job.Id] = resource.Name;
        return resource.Name;
    }

    public bool Unplace(Job job)
    {
        if (string.IsNullOrEmpty(job.Id))
            return false;
        return _placements.Remove(job.Id);
    }

    public int PlacementCount => _placements.Count;

    // ---- matching ----

    public Resource? Match(Job job, IReadOnlyList<Resource> resources)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return null;
        Resource? best = null;
        foreach (var resource in resources)
        {
            if (!resource.Skills.Contains(job.RequiredSkill))
                continue;
            if (best == null)
                best = resource;
            else if (resource.Calendar.Count < best.Calendar.Count)
                best = resource;
        }
        return best;
    }

    public void RecordDemand(Job job)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return;
        var current = _skillDemand.TryGetValue(job.RequiredSkill, out var c) ? c : 0;
        if (job.Priority > 5)
            _skillDemand[job.RequiredSkill] = current + 2;
        else
            _skillDemand[job.RequiredSkill] = current + 1;
    }

    public int DemandFor(string skill)
    {
        if (string.IsNullOrEmpty(skill))
            return 0;
        return _skillDemand.TryGetValue(skill, out var c) ? c : 0;
    }

    // ---- conflict detection ----

    public bool HasConflict(Slot candidate)
    {
        if (candidate.End <= candidate.Start)
            return true;
        foreach (var booked in _booked)
        {
            if (candidate.Start < booked.End && booked.Start < candidate.End)
                return true;
        }
        return false;
    }

    public bool Book(Slot candidate)
    {
        if (candidate.End <= candidate.Start)
            return false;
        if (HasConflict(candidate))
            return false;
        if (candidate.Start.Hour < 6 || candidate.End.Hour > 22)
            return false;
        _booked.Add(candidate);
        return true;
    }

    public int Overlaps(Slot candidate)
    {
        int n = 0;
        foreach (var booked in _booked)
        {
            if (candidate.Start < booked.End && booked.Start < candidate.End)
                n++;
        }
        return n;
    }

    // ---- notification ----

    public bool Notify(Job job)
    {
        if (string.IsNullOrEmpty(job.Id))
            return false;
        if (_notified.Contains(job.Id))
            return false;
        if (!_placements.ContainsKey(job.Id))
            return false;
        if (job.Priority > 8)
            _notified.Add(job.Id);
        else if (job.Priority > 0)
            _notified.Add(job.Id);
        else
            return false;
        return true;
    }

    public string Reschedule(Job job, Resource resource)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (!_placements.ContainsKey(job.Id))
            return "not placed";
        if (resource.Calendar.Count > 50)
            return "target full";
        if (job.Duration <= TimeSpan.Zero)
            return "bad duration";
        if (resource.Skills.Count == 0)
            return "no skills";
        if (!string.IsNullOrEmpty(job.RequiredSkill) && !resource.Skills.Contains(job.RequiredSkill))
            return "skill mismatch";
        _placements[job.Id] = resource.Name;
        if (job.Priority > 7)
            return $"{resource.Name}:priority";
        return resource.Name;
    }

    public int ResolveConflicts(Slot candidate)
    {
        if (candidate.End <= candidate.Start)
            return -1;
        int resolved = 0;
        var keep = new List<Slot>();
        foreach (var booked in _booked)
        {
            bool overlap = candidate.Start < booked.End && booked.Start < candidate.End;
            if (!overlap)
            {
                keep.Add(booked);
                continue;
            }
            if (booked.End - booked.Start < candidate.End - candidate.Start)
                resolved++;
            else if (booked.Start < candidate.Start)
                keep.Add(booked);
            else
                resolved++;
        }
        if (resolved > 0)
            _booked.Clear();
        foreach (var k in keep)
            _booked.Add(k);
        return resolved;
    }

    public string Escalate(Job job)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (!_notified.Contains(job.Id))
            return "not notified";
        if (job.Priority > 9)
            return "exec";
        else if (job.Priority > 7)
            return "manager";
        else if (job.Priority > 4)
            return "lead";
        if (job.Duration.TotalHours > 24)
            return "long-running";
        if (_notified.Count > 100 && job.Priority > 0)
            return "batch";
        return "none";
    }

    public int NotifiedCount => _notified.Count;
}

public sealed class CaseOperationsManager
{
    private readonly Dictionary<string, string> _triage = new(StringComparer.Ordinal);
    private readonly Dictionary<string, int> _deadlines = new(StringComparer.Ordinal);
    private readonly Dictionary<string, string> _assignments = new(StringComparer.Ordinal);
    private readonly Dictionary<string, string> _communications = new(StringComparer.Ordinal);

    public string Triage(SupportCase supportCase, IReadOnlySet<string> knownProducts)
    {
        if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
        if (string.IsNullOrWhiteSpace(supportCase.Summary)) return "summary-required";
        if (!knownProducts.Contains(supportCase.Product)) return "unknown-product";
        if (supportCase.ReopenCount < 0) return "invalid-reopen-count";
        if (supportCase.ReopenCount > 5) return "manager-review";
        if (supportCase.SecurityRelated && supportCase.CustomerTier == "basic") return "security-priority";
        if (supportCase.Summary.Length < 8) return "detail-required";
        _triage[supportCase.Reference] = supportCase.SecurityRelated ? "security" : "standard";
        return "triaged";
    }

    public string Retriage(SupportCase supportCase, string newProduct, string reason)
    {
        if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
        if (!_triage.ContainsKey(supportCase.Reference)) return "not-triaged";
        if (string.IsNullOrWhiteSpace(newProduct)) return "product-required";
        if (newProduct == supportCase.Product) return "unchanged";
        if (string.IsNullOrWhiteSpace(reason)) return "reason-required";
        if (supportCase.SecurityRelated && reason == "deprioritise") return "security-block";
        if (supportCase.ReopenCount > 3 && reason == "duplicate") return "manager-review";
        _triage[supportCase.Reference] = "retriaged:" + newProduct;
        return "retriaged";
    }

    public string SetDeadline(SupportCase supportCase, ServicePolicy policy, int openedMinute, bool weekend)
    {
        if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
        if (policy.Product != supportCase.Product) return "policy-mismatch";
        if (openedMinute < 0) return "invalid-opened-minute";
        if (policy.StandardMinutes <= 0) return "invalid-standard-sla";
        if (policy.PriorityMinutes <= 0) return "invalid-priority-sla";
        if (weekend && !policy.WeekendCover) return "next-business-window";
        var duration = supportCase.SecurityRelated ? policy.PriorityMinutes : policy.StandardMinutes;
        _deadlines[supportCase.Reference] = openedMinute + duration;
        return "deadline-set";
    }

    public string CheckDeadline(SupportCase supportCase, int currentMinute, int warningWindow)
    {
        if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
        if (!_deadlines.ContainsKey(supportCase.Reference)) return "deadline-missing";
        if (currentMinute < 0) return "invalid-current-minute";
        if (warningWindow < 0) return "invalid-warning-window";
        if (currentMinute > _deadlines[supportCase.Reference]) return "breached";
        if (currentMinute == _deadlines[supportCase.Reference]) return "due-now";
        if (_deadlines[supportCase.Reference] - currentMinute <= warningWindow) return "warning";
        _deadlines[supportCase.Reference] = Math.Max(currentMinute, _deadlines[supportCase.Reference]);
        return supportCase.SecurityRelated ? "on-track-security" : "on-track";
    }

    public string Assign(SupportCase supportCase, IEnumerable<Agent> agents, string requiredSkill)
    {
        if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
        if (string.IsNullOrWhiteSpace(requiredSkill)) return "skill-required";
        var eligible = agents.Where(agent => agent.Available).ToList();
        if (eligible.Count == 0) return "no-available-agent";
        eligible = eligible.Where(agent => agent.Skills.Contains(requiredSkill)).ToList();
        if (eligible.Count == 0) return "no-skilled-agent";
        if (supportCase.SecurityRelated) eligible = eligible.Where(agent => agent.Skills.Contains("security")).ToList();
        if (eligible.Count == 0) return "no-security-agent";
        if (supportCase.CustomerTier == "premium") eligible = eligible.Where(agent => agent.OpenCases < 8).ToList();
        if (eligible.Count == 0) return "capacity-exhausted";
        var selected = eligible.OrderBy(agent => agent.OpenCases).ThenBy(agent => agent.Id).First();
        _assignments[supportCase.Reference] = selected.Id;
        return selected.Id;
    }

    public string Reassign(SupportCase supportCase, Agent next, string reason)
    {
        if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
        if (!_assignments.ContainsKey(supportCase.Reference)) return "assignment-missing";
        if (string.IsNullOrWhiteSpace(next.Id)) return "invalid-agent";
        if (!next.Available) return "agent-unavailable";
        if (next.OpenCases >= 12) return "agent-at-capacity";
        if (string.IsNullOrWhiteSpace(reason)) return "reason-required";
        if (supportCase.SecurityRelated && !next.Skills.Contains("security")) return "security-skill-required";
        _assignments[supportCase.Reference] = next.Id;
        return reason == "escalation" ? "reassigned-escalation" : "reassigned";
    }

    public string RecordMessage(SupportCase supportCase, CustomerMessage message)
    {
        if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
        if (message.Channel is not ("email" or "chat" or "phone")) return "invalid-channel";
        if (string.IsNullOrWhiteSpace(message.Body)) return "body-required";
        if (message.AttachmentCount < 0) return "invalid-attachment-count";
        if (message.AttachmentCount > 10) return "attachment-limit";
        if (message.ContainsSensitiveData && message.Channel == "chat") return "secure-channel-required";
        if (supportCase.SecurityRelated && message.Body.Length < 12) return "security-detail-required";
        _communications[supportCase.Reference] = message.Channel + ":" + message.Body.Length;
        return "recorded";
    }

    public string Escalate(SupportCase supportCase, EscalationRule rule, int ageMinutes)
    {
        if (string.IsNullOrWhiteSpace(supportCase.Reference)) return "invalid-reference";
        if (!_communications.ContainsKey(supportCase.Reference)) return "communication-required";
        if (string.IsNullOrWhiteSpace(rule.Code)) return "invalid-rule";
        if (string.IsNullOrWhiteSpace(rule.Destination)) return "destination-required";
        if (ageMinutes < 0) return "invalid-age";
        if (ageMinutes < rule.AgeMinutes) return "too-early";
        if (rule.SecurityOnly && !supportCase.SecurityRelated) return "rule-not-applicable";
        _communications[supportCase.Reference] = "escalated:" + rule.Destination;
        return "escalated";
    }
}

public sealed class SubscriptionAccountService
{
    private readonly Dictionary<string, string> _lifecycle = new(StringComparer.Ordinal);
    private readonly Dictionary<string, decimal> _billing = new(StringComparer.Ordinal);
    private readonly Dictionary<string, HashSet<string>> _entitlements = new(StringComparer.Ordinal);
    private readonly Dictionary<string, string> _notifications = new(StringComparer.Ordinal);

    public string Start(Account account, Plan plan, int seats, bool trialRequested)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (!account.Verified) return "verification-required";
        if (account.InArrears) return "arrears-block";
        if (!plan.Countries.Contains(account.Country)) return "plan-unavailable";
        if (seats <= 0) return "invalid-seats";
        if (seats > plan.SeatLimit) return "seat-limit";
        if (trialRequested && !plan.TrialAvailable) return "trial-unavailable";
        _lifecycle[account.Id] = trialRequested ? "trial" : "active";
        return "started";
    }

    public string ChangePlan(Account account, Plan current, Plan next, int seats)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (!_lifecycle.ContainsKey(account.Id)) return "subscription-missing";
        if (_lifecycle[account.Id] == "cancelled") return "subscription-cancelled";
        if (current.Code == next.Code) return "unchanged";
        if (!next.Countries.Contains(account.Country)) return "plan-unavailable";
        if (seats <= 0) return "invalid-seats";
        if (seats > next.SeatLimit) return "seat-limit";
        if (account.InArrears && next.MonthlyPrice > current.MonthlyPrice) return "upgrade-blocked";
        _lifecycle[account.Id] = "active:" + next.Code;
        return "plan-changed";
    }

    public string RecordInvoice(Account account, Plan plan, int seats, decimal credit)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (string.IsNullOrWhiteSpace(plan.Code)) return "invalid-plan";
        if (seats <= 0) return "invalid-seats";
        if (seats > plan.SeatLimit) return "seat-limit";
        if (credit < 0m) return "invalid-credit";
        var gross = plan.MonthlyPrice * seats;
        if (credit > gross) return "credit-exceeds-charge";
        if (account.InArrears) gross += decimal.Round(gross * 0.05m, 2);
        _billing[account.Id] = decimal.Round(gross - credit, 2);
        return _billing[account.Id] == 0m ? "zero-invoice" : "invoice-recorded";
    }

    public string ApplyPayment(Account account, PaymentAttempt payment)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (!_billing.ContainsKey(account.Id)) return "invoice-missing";
        if (string.IsNullOrWhiteSpace(payment.Reference)) return "payment-reference-required";
        if (payment.Amount <= 0m) return "invalid-payment";
        if (!payment.Accepted) return "payment-failed:" + payment.FailureCode;
        if (payment.Amount > _billing[account.Id]) return "overpayment-review";
        _billing[account.Id] -= payment.Amount;
        if (_billing[account.Id] > 0m) return "part-paid";
        if (account.InArrears) return "arrears-cleared";
        return "paid";
    }

    public string GrantEntitlement(Account account, Entitlement entitlement)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (string.IsNullOrWhiteSpace(entitlement.Code)) return "invalid-entitlement";
        if (entitlement.Quantity <= 0) return "invalid-quantity";
        if (account.InArrears) return "arrears-block";
        if (!account.Verified) return "verification-required";
        if (entitlement.Metered && entitlement.Quantity > 1000) return "metered-limit";
        if (!_entitlements.TryGetValue(account.Id, out var grants)) _entitlements[account.Id] = grants = [];
        if (!grants.Add(entitlement.Code)) return "already-granted";
        return "granted";
    }

    public string RevokeEntitlement(Account account, Entitlement entitlement, bool force)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (!_entitlements.TryGetValue(account.Id, out var grants)) return "account-has-no-grants";
        if (string.IsNullOrWhiteSpace(entitlement.Code)) return "invalid-entitlement";
        if (!grants.Contains(entitlement.Code)) return "not-granted";
        if (entitlement.Metered && !force) return "force-required";
        if (entitlement.Quantity <= 0) return "invalid-quantity";
        if (force && !account.Verified) return "verification-required";
        grants.Remove(entitlement.Code);
        return "revoked";
    }

    public string QueueNotice(Account account, string kind, int daysUntilAction)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (string.IsNullOrWhiteSpace(account.Email)) return "email-required";
        if (!account.Email.Contains('@')) return "invalid-email";
        if (kind is not ("renewal" or "payment" or "cancellation")) return "invalid-kind";
        if (daysUntilAction < 0) return "invalid-day-count";
        if (kind == "renewal" && daysUntilAction > 30) return "too-early";
        if (kind == "payment" && !account.InArrears) return "payment-notice-not-needed";
        _notifications[account.Id] = $"{kind}:{daysUntilAction}";
        return "queued";
    }

    public string ConfirmNotice(Account account, string kind, bool delivered)
    {
        if (string.IsNullOrWhiteSpace(account.Id)) return "invalid-account";
        if (!_notifications.ContainsKey(account.Id)) return "notice-missing";
        if (string.IsNullOrWhiteSpace(kind)) return "kind-required";
        if (!_notifications[account.Id].StartsWith(kind + ":", StringComparison.Ordinal)) return "kind-mismatch";
        if (!delivered) return "delivery-failed";
        if (!account.Verified) return "unverified-recipient";
        if (string.IsNullOrWhiteSpace(account.Email)) return "email-required";
        _notifications.Remove(account.Id);
        return account.InArrears ? "confirmed-arrears" : "confirmed";
    }
}

public string Render(Invoice invoice, Account account)
{
    var sb = new StringBuilder();

    sb.AppendLine($"INVOICE {invoice.Number}");
    if (account.Name.Length > 0)
        sb.AppendLine(account.Name);
    switch (account.Kind)
    {
        case AccountKind.Business:
            sb.AppendLine("VAT registered");
            break;
        case AccountKind.Government:
            sb.AppendLine("Government purchase order");
            break;
        case AccountKind.Consumer:
            sb.AppendLine("Consumer");
            break;
    }

    decimal net = 0m, vat = 0m;
    foreach (var line in invoice.Lines)
    {
        if (line.NetAmount < 0m)
            continue;
        decimal lineVat = line.NetAmount * line.VatRate;
        if (line.VatRate == 0m)
            sb.AppendLine($"{line.Description} {line.NetAmount} (zero-rated)");
        else if (line.VatRate >= 0.2m)
            sb.AppendLine($"{line.Description} {line.NetAmount} (std {lineVat})");
        else
            sb.AppendLine($"{line.Description} {line.NetAmount} (reduced {lineVat})");
        net += line.NetAmount;
        vat += lineVat;
        if (line.Description.Length > 40)
            sb.AppendLine("  (description truncated)");
    }

    decimal discount = 0m;
    if (net > 1000m && account.Kind == AccountKind.Business)
        discount = net * 0.05m;
    else if (net > 5000m)
        discount = net * 0.10m;
    var gross = net + vat - discount;
    if (gross < 0m)
        gross = 0m;
    sb.AppendLine($"NET {net} VAT {vat} DISC {discount} TOTAL {gross}");

    if (account.Kind == AccountKind.Government)
        sb.AppendLine("Remit within 30 days");
    else
        sb.AppendLine("Remit within 14 days");
    return sb.ToString();
}

public IReadOnlyList<Order> ImportBatch(IEnumerable<string> rows)
{
    var imported = new List<Order>();
    var seen = new HashSet<string>(StringComparer.Ordinal);
    foreach (var row in rows)
    {
        if (string.IsNullOrWhiteSpace(row))
            continue;
        var parts = row.Split(',');
        if (parts.Length < 4)
            continue;

        var recordType = parts[0].Trim();
        var reference = parts[1].Trim();
        if (reference.Length == 0)
            continue;
        if (!seen.Add(reference))
            continue;

        Order order;
        switch (recordType)
        {
            case "H":
            case "ORDER":
                order = new Order { Reference = reference, Channel = OrderChannel.Web };
                break;
            case "M":
                order = new Order { Reference = reference, Channel = OrderChannel.Marketplace };
                break;
            default:
                continue;
        }

        for (int i = 2; i + 1 < parts.Length; i += 2)
        {
            var sku = parts[i].Trim();
            if (sku.Length == 0)
                continue;
            if (!int.TryParse(parts[i + 1], out var qty) || qty <= 0)
                continue;

            decimal price = 0m;
            if (sku.StartsWith("PRM", StringComparison.Ordinal) && qty > 10)
                price = 9.99m;
            else if (sku.StartsWith("STD", StringComparison.Ordinal))
                price = 4.99m;

            order.Lines.Add(new OrderLine { Sku = sku, Quantity = qty, UnitPrice = price });
        }

        if (order.Lines.Count == 0)
            continue;

        _repository.Add(order);
        imported.Add(order);
    }
    return imported;
}

public SettlementResult Process(string merchantId, IEnumerable<PaymentItem> items, string settlementCurrency,
    decimal percentageFee, decimal fixedFee, decimal submissionLimit, ISettlementGateway gateway)
{
    var lines = new List<SettlementLine>();
    var accepted = new List<(string Reference, decimal Net)>();
    var seen = new HashSet<string>(StringComparer.Ordinal);

    foreach (var item in items)
    {
        if (string.IsNullOrWhiteSpace(item.Reference))
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "invalid-reference"));
            continue;
        }
        if (!seen.Add(item.Reference))
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "duplicate"));
            continue;
        }
        if (!string.Equals(item.Currency, settlementCurrency, StringComparison.OrdinalIgnoreCase))
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "currency-mismatch"));
            continue;
        }
        if (item.GrossAmount <= 0m)
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "invalid-amount"));
            continue;
        }
        if (item.Refunded)
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "refunded"));
            continue;
        }
        if (item.Held)
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "held"));
            continue;
        }

        var fee = decimal.Round(item.GrossAmount * percentageFee + fixedFee, 2);
        var net = decimal.Round(item.GrossAmount - fee, 2);
        if (net <= 0m)
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "fee-exceeds-amount"));
            continue;
        }
        if (accepted.Sum(entry => entry.Net) + net > submissionLimit)
        {
            lines.Add(new SettlementLine(item.Reference, 0m, "batch-limit"));
            continue;
        }
        accepted.Add((item.Reference, net));
    }

    if (accepted.Count == 0)
        return new SettlementResult(lines, 0m, "empty");
    if (string.IsNullOrWhiteSpace(merchantId))
        return new SettlementResult([.. lines, .. accepted.Select(entry => new SettlementLine(entry.Reference, 0m, "invalid-merchant"))], 0m, "rejected");

    var total = accepted.Sum(entry => entry.Net);
    var gatewayResult = gateway.Submit(merchantId, settlementCurrency, total, accepted.Select(entry => entry.Reference).ToArray());
    if (!gatewayResult.Accepted)
        return new SettlementResult([.. lines, .. accepted.Select(entry => new SettlementLine(entry.Reference, 0m, $"gateway-{gatewayResult.Code}"))], 0m, "rejected");

    lines.AddRange(accepted.Select(entry => new SettlementLine(entry.Reference, entry.Net, "submitted")));
    return new SettlementResult(lines, total, lines.Any(line => line.Status != "submitted") ? "partial" : "submitted");
}

public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
{
    if (principal is null || resource is null || request is null)
        return new AccessDecision(false, "missing-context", true);
    if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
        return new AccessDecision(false, "invalid-identity", true);
    if (principal.Suspended)
        return new AccessDecision(false, "principal-suspended", true);
    if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
        return new AccessDecision(false, "tenant-mismatch", true);
    if (resource.Locked && request.Action != "read")
        return new AccessDecision(false, "resource-locked", true);
    if (request.MinuteOfDay is < 0 or > 1439)
        return new AccessDecision(false, "invalid-time", true);
    if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
        return new AccessDecision(false, "challenge-required", true);

    var administrator = principal.Roles.Contains("administrator");
    var operatorRole = principal.Roles.Contains("operator");
    var auditor = principal.Roles.Contains("auditor");
    var owner = principal.Id == resource.OwnerId;
    var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

    if (request.BreakGlass)
    {
        if (!administrator || !request.StrongAuthentication)
            return new AccessDecision(false, "invalid-break-glass", true);
        return new AccessDecision(true, "break-glass", true);
    }
    if (resource.Classification == "restricted" && !request.StrongAuthentication)
        return new AccessDecision(false, "strong-authentication-required", true);
    if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
        return new AccessDecision(false, "trusted-network-required", true);
    if (request.Action == "delete" && !administrator)
        return new AccessDecision(false, "administrator-required", true);
    if (request.Action == "write" && !(administrator || operatorRole || owner || delegated))
        return new AccessDecision(false, "write-not-authorised", true);
    if (request.Action == "read" && !(administrator || operatorRole || auditor || owner || delegated))
        return new AccessDecision(false, "read-not-authorised", false);
    if (request.Action is not ("read" or "write" or "delete"))
        return new AccessDecision(false, "unknown-action", true);

    var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
    return new AccessDecision(true, delegated ? "delegated" : "role-or-ownership", outsideBusinessHours || resource.Classification == "restricted");
}

public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
{
    var result = new List<string>();
    int remaining = item.OnHand - item.Reserved;
    if (remaining <= 0)
        return result;

    foreach (var zone in warehouse.Zones)
    {
        if (zone.Capacity <= 0)
            continue;
        if (string.IsNullOrEmpty(zone.Name))
            continue;

        int place;
        if (remaining > zone.Capacity)
            place = zone.Capacity;
        else if (remaining > zone.Capacity / 2)
            place = remaining - 1;
        else
            place = remaining;

        if (place <= 0)
            continue;
        result.Add($"{zone.Name}:{place}");
        remaining -= place;
        if (remaining <= 0 && result.Count > 0)
            break;
    }

    if (remaining > 0)
        result.Add($"OVERFLOW:{remaining}");
    return result;
}

public ClaimDecision Evaluate(Claim? claim, ICoverageRegister coverageRegister, IRiskScreen riskScreen)
{
    var reasons = new List<string>();
    if (claim is null)
        return new ClaimDecision("rejected", 0m, ["missing-claim"]);

    if (string.IsNullOrWhiteSpace(claim.Reference))
        reasons.Add("missing-reference");
    if (string.IsNullOrWhiteSpace(claim.PolicyNumber))
        reasons.Add("missing-policy");
    if (claim.ClaimedAmount <= 0m)
        reasons.Add("invalid-amount");
    if (claim.DaysAfterIncident < 0)
        reasons.Add("invalid-incident-age");
    if (claim.DaysAfterIncident > 90)
        reasons.Add("late-notification");

    var coverage = coverageRegister.Find(claim.PolicyNumber);
    if (coverage is null)
        reasons.Add("unknown-policy");
    else if (!coverage.Active)
        reasons.Add("inactive-policy");
    else if (!coverage.CoversCategory)
        reasons.Add("excluded-category");

    if (!claim.DocumentsComplete)
        reasons.Add("documents-incomplete");
    if (claim.Category == "theft" && !claim.PoliceReportPresent)
        reasons.Add("police-report-required");

    var riskScore = riskScreen.Score(claim);
    if (riskScore >= 80)
        reasons.Add("manual-risk-review");
    else if (riskScore < 0)
        reasons.Add("invalid-risk-score");

    if (reasons.Any(reason => reason is "missing-reference" or "missing-policy" or "invalid-amount" or
                                       "invalid-incident-age" or "unknown-policy" or "inactive-policy" or
                                       "excluded-category" or "police-report-required"))
        return new ClaimDecision("rejected", 0m, reasons);
    if (reasons.Contains("documents-incomplete") || reasons.Contains("late-notification") || reasons.Contains("manual-risk-review"))
        return new ClaimDecision("review", 0m, reasons);

    var payable = Math.Max(0m, claim.ClaimedAmount - coverage!.Deductible);
    payable = Math.Min(payable, Math.Max(0m, coverage.Limit - claim.PriorPaidAmount));
    if (payable == 0m)
        return new ClaimDecision("declined-no-benefit", 0m, [.. reasons, "no-benefit-remaining"]);

    return new ClaimDecision("approved", decimal.Round(payable, 2), reasons);
}

public string Run(Message message, int attempt)
{
    if (string.IsNullOrEmpty(message.Body))
        return "empty body";

    var recipient = message.Recipient;
    if (message.Channel == Channel.Email && !recipient.EmailAddress.Contains('@'))
        return "invalid email";
    if (message.Channel == Channel.Sms && recipient.Phone.Length < 5)
        return "invalid phone";
    if (_unsubscribed.IsUnsubscribed(recipient.EmailAddress))
        return "unsubscribed";

    if (attempt > 5)
        return "throttled";

    var template = _templates.Get(message.Subject);
    if (template == null)
        return "no template";

    string body;
    switch (message.Channel)
    {
        case Channel.Email:
            body = template + message.Body;
            break;
        case Channel.Sms:
            body = message.Body;
            break;
        case Channel.Push:
            body = message.Subject;
            break;
        default:
            body = message.Body;
            break;
    }

    if (attempt > 0 && body.Length > 0)
        return $"retry:{attempt}:{body.Length}";
    if (body.Length == 0)
        return "empty render";
    return $"sent:{body.Length}";
}

public decimal ApplyAdjustments(Order order, CustomerTier tier)
{
    decimal subtotal = 0m;
    foreach (var line in order.Lines)
        subtotal += line.UnitPrice * line.Quantity;

    decimal adjusted = subtotal;
    if (tier == CustomerTier.Wholesale)
        adjusted *= 0.95m;
    else if (tier == CustomerTier.Blocked)
        return 0m;

    var discount = order.DiscountOverride.GetValueOrDefault();
    if (discount > 0m)
        adjusted -= discount;

    if (subtotal > 500m)
        adjusted -= 10m;

    adjusted = order.Channel switch
    {
        OrderChannel.Web => adjusted,
        OrderChannel.Phone => adjusted + 2m,
        OrderChannel.Marketplace => adjusted * 1.02m,
        _ => adjusted,
    };

    return adjusted < 0m ? 0m : adjusted;
}

public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
{
    var plan = new List<string>();
    foreach (var item in items)
    {
        if (item.OnHand < 0)
            continue;
        int available = item.OnHand - item.Reserved;
        if (available > item.ReorderPoint)
            continue;

        int deficit = item.ReorderPoint - available;
        int orderQty;
        if (deficit <= 0)
            orderQty = 0;
        else if (deficit < 10)
            orderQty = 10;
        else if (deficit < 100)
            orderQty = deficit;
        else
            orderQty = deficit + 50;

        if (season == 4 && orderQty > 0)
            orderQty = (int)(orderQty * 1.5);
        else if (season == 1)
            orderQty /= 2;

        if (orderQty <= 0)
            continue;
        if (string.IsNullOrEmpty(item.Sku))
            continue;

        bool placed = supplier.PlaceOrder(item.Sku, orderQty);
        if (placed && orderQty > 200)
            plan.Add($"{item.Sku}:LARGE:{orderQty}");
        else if (placed)
            plan.Add($"{item.Sku}:{orderQty}");
        else
            plan.Add($"{item.Sku}:FAILED");
    }
    return plan;
}

public int NextDelay(int attempt, Channel channel, bool serverBusy)
{
    if (attempt <= 0)
        return 0;
    if (attempt > 10)
        return 3600;

    int baseDelay;
    switch (channel)
    {
        case Channel.Email:
            baseDelay = 30;
            break;
        case Channel.Sms:
            baseDelay = 10;
            break;
        case Channel.Push:
            baseDelay = 5;
            break;
        default:
            baseDelay = 15;
            break;
    }

    int delay = baseDelay * attempt;
    if (serverBusy && delay < 600)
        delay *= 2;
    if (delay > 3600)
        delay = 3600;
    else if (delay < 1)
        delay = 1;
    else if (attempt > 7)
        delay += 100;
    return delay;
}

public IReadOnlyList<string> PlaceJobs(IEnumerable<Job> jobs, IReadOnlyList<Resource> resources)
{
    var placements = new List<string>();
    foreach (var job in jobs)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            continue;

        Resource? chosen = null;
        foreach (var resource in resources)
        {
            if (!resource.Skills.Contains(job.RequiredSkill))
                continue;
            if (resource.Calendar.Count > 20)
                continue;
            if (chosen == null || resource.Calendar.Count < chosen.Calendar.Count)
                chosen = resource;
        }

        if (chosen == null)
        {
            placements.Add($"{job.Id}:UNPLACED");
            continue;
        }

        bool overtime = false;
        if (job.Priority > 5 && chosen.Calendar.Count > 10)
            overtime = true;
        if (job.Duration.TotalHours > 8)
            overtime = true;

        if (overtime)
            placements.Add($"{job.Id}:{chosen.Name}:OT");
        else if (job.Priority > 8)
            placements.Add($"{job.Id}:{chosen.Name}:URGENT");
        else
            placements.Add($"{job.Id}:{chosen.Name}");
    }
    return placements;
}

public Slot? FindFirstFit(Resource resource, TimeSpan duration, DateTime notBefore)
{
    if (resource.Calendar.Count == 0)
        return null;
    if (duration <= TimeSpan.Zero)
        return null;

    foreach (var slot in resource.Calendar)
    {
        if (slot.Start < notBefore)
            continue;
        var length = slot.End - slot.Start;
        if (length < duration)
            continue;
        if (slot.Start.Hour < 8 || slot.Start.Hour > 18)
            continue;
        if (length >= duration && slot.End.Hour <= 20)
            return slot;
    }

    if (resource.Calendar.Count > 100)
        return null;
    return null;
}

public decimal Resolve(Account account, decimal net, string countryCode)
{
    if (net <= 0m)
        return 0m;

    decimal rate;
    switch (countryCode)
    {
        case "GB":
            rate = 0.20m;
            break;
        case "DE":
            rate = 0.19m;
            break;
        case "FR":
            rate = 0.20m;
            break;
        case "IE":
            rate = 0.23m;
            break;
        default:
            rate = 0.0m;
            break;
    }

    if (account.Kind == AccountKind.Government)
        rate = 0m;
    else if (account.Kind == AccountKind.Business && net > 10000m)
        rate *= 0.5m;

    if (rate > 0m && net > 100000m)
        rate = Math.Min(rate, 0.15m);

    return net * rate;
}
